@@ -40,41 +44,407 @@ public:
     alignas(sizeof(uint256)) uint256 m_stack_space[limit];
 };

-/// Checkpoint-capable stack. This correctness-first fallback stores every frame eagerly.
+/// Checkpoint-capable stack.
+///
+/// Items live in the stack space supplied to the constructor. A checkpoint records only
+/// the height, a position in an undo log and the previous protection watermark. Before a
+/// slot below the watermark (the highest height any live checkpoint covers) is first
+/// overwritten after a checkpoint, its old value is appended to the undo log, so creating
+/// a checkpoint is O(1). Restoring sets the height at once and replays the log backwards
+/// down to the checkpoint's position before the next access of any item.
+///
+/// The undo log is a chain of fixed-size blocks. Blocks are carved downwards from the end
+/// of the stack space while they fit above both the items and the watermark, and move to
+/// the heap if the stack grows into them; other blocks are heap allocated.
 class StackTop
 {
+    /// One block of the undo log: the saved values and the slots they belong to.
+    struct UndoBlock
+    {
+        static constexpr uint32_t size = 60;
+        /// The saved values; the union keeps them from being zeroed on construction.
+        union
+        {
+            uint256 value[size];
+        };
+        uint16_t slot[size];
+        UndoBlock* prev;
+        UndoBlock() noexcept {}
+    };
+    /// The number of stack slots a block occupies when carved from the stack space.
+    static constexpr uint32_t block_slots = sizeof(UndoBlock) / sizeof(uint256);
+    static_assert(sizeof(UndoBlock) == block_slots * sizeof(uint256));
+
+    /// Checkpoint interval tag; not a character type, so tag stores alias nothing else.
+    enum class Epoch : uint8_t
+    {
+    };
+
+    /// Slots with a per-interval "already saved" tag; higher slots are saved on every write.
+    static constexpr size_t tagged_slots = 1024;
+
+    /// Slots kept free above the items when carving an undo block from the stack space.
+    static constexpr size_t popped_margin = 8;
+
 public:
+    /// The number of items of a stack created by the default constructor.
     static constexpr size_t capacity = 1024;
+
+    /// The state a checkpoint needs to restore the stack.
+    struct Mark
+    {
+        uint32_t log_size;
+        uint16_t height;
+        uint16_t watermark;
+    };
+
     size_t height{0};
-    std::array<uint256, capacity> values{};
-    StackTop() = default;
-    StackTop(uint256*, uint256*) {}
+
+private:
+    uint256* m_base{nullptr};              ///< Bottom item of the stack.
+    mutable uint32_t m_watermark{0};       ///< Slots below this are covered by a checkpoint;
+                                           ///< all slots while a replay is pending.
+    mutable bool m_pending{false};         ///< The undo log must still be replayed.
+    Epoch m_epoch{1};                      ///< Tag of the current checkpoint interval.
+    bool m_owned{false};                   ///< m_base was allocated by this object.
+    mutable uint32_t m_floor{0};           ///< Lowest slot used by undo blocks in the space.
+    mutable uint32_t m_used{UndoBlock::size};  ///< Entries in the newest undo block.
+    mutable uint32_t m_blocks{0};          ///< Blocks in the undo log.
+    uint32_t m_target{0};                  ///< Log size to replay down to when pending.
+    uint32_t m_restored_watermark{0};      ///< The watermark once the pending replay is done.
+    uint32_t m_end{0};                     ///< Number of slots in the stack space.
+    mutable UndoBlock* m_block{nullptr};   ///< Newest undo block.
+    mutable UndoBlock* m_spare{nullptr};   ///< Emptied heap blocks kept for reuse.
+    Epoch m_tags[tagged_slots]{};          ///< Interval in which each slot was last saved.
+
+public:
+    StackTop() : m_base{new uint256[capacity]}, m_owned{true}, m_floor{capacity}, m_end{capacity} {}
+    StackTop(uint256* begin, uint256* end) noexcept
+      : m_base{begin},
+        m_floor{static_cast<uint32_t>(end - begin)},
+        m_end{static_cast<uint32_t>(end - begin)}
+    {}
+
+    StackTop(const StackTop& other) { copy_from(other); }
+    StackTop(StackTop&& other) noexcept { take(other); }
+    StackTop& operator=(const StackTop& other)
+    {
+        if (this != &other)
+        {
+            release();
+            copy_from(other);
+        }
+        return *this;
+    }
+    StackTop& operator=(StackTop&& other) noexcept
+    {
+        if (this != &other)
+        {
+            release();
+            take(other);
+        }
+        return *this;
+    }
+    ~StackTop() { release(); }
+
     /// push an item onto current stack top
-    inline void push(const uint256& item) {
-        values[height++] = item;
+    inline void push(const uint256& item)
+    {
+        const size_t slot = height;
+        if (slot < m_watermark)
+            save(slot);
+        else if (slot >= m_floor) [[unlikely]]
+            evict();
+        m_base[slot] = item;
+        height = slot + 1;
     }
     /// pop an item and return it
-    inline const uint256 &pop() {
-        height -= 1;
-        return values[height];
+    inline const uint256& pop()
+    {
+        settle();
+        return m_base[--height];
     }
     /// equivalent to get(0)
-    inline const uint256& top() {
-        return get(0);
+    inline const uint256& top() const
+    {
+        settle();
+        return m_base[height - 1];
     }
     /// equivalent to get(index)
-    inline const uint256& operator[](size_t index) const {
-        return get(index);
-    }
+    inline const uint256& operator[](size_t index) const { return get(index); }
     /// read item on stack, counting from stack top to stack bottom
-    inline const uint256& get(size_t index) const {
-        index = height - 1 - index;
-        return values[index];
+    inline const uint256& get(size_t index) const
+    {
+        settle();
+        return m_base[height - 1 - index];
     }
     /// write item to stack
-    inline uint256& get_mut(size_t index) {
-        index = height - 1 - index;
-        return values[index];
+    inline uint256& get_mut(size_t index)
+    {
+        const size_t slot = height - 1 - index;
+        if (slot < m_watermark)
+            save(slot);
+        return m_base[slot];
+    }
+
+    /// Starts protecting the current items and returns what restoring them needs.
+    inline Mark mark() noexcept
+    {
+        settle();
+        const Mark m{log_size(), static_cast<uint16_t>(height), static_cast<uint16_t>(m_watermark)};
+        if (height > m_watermark)
+            m_watermark = static_cast<uint32_t>(height);
+        next_epoch();
+        return m;
+    }
+
+    /// Restores the items and height recorded by mark().
+    inline void restore(const Mark& m) noexcept
+    {
+        if (m.log_size < log_size() && (!m_pending || m.log_size < m_target))
+        {
+            m_target = m.log_size;
+            m_pending = true;
+        }
+        height = m.height;
+        const uint32_t watermark = m.height > m.watermark ? m.height : m.watermark;
+        if (m_pending)
+        {
+            m_restored_watermark = watermark;
+            m_watermark = ~uint32_t{0};
+        }
+        else
+            m_watermark = watermark;
+        next_epoch();
+    }
+
+    /// Moves the stack onto other storage if it currently uses `from`.
+    void rebind(const uint256* from, uint256* to) noexcept
+    {
+        if (!m_owned && m_base == from)
+            m_base = to;
+    }
+
+private:
+    [[nodiscard]] inline uint32_t log_size() const noexcept
+    {
+        return m_blocks * UndoBlock::size + m_used - UndoBlock::size;
+    }
+
+    inline void settle() const noexcept
+    {
+        if (m_pending) [[unlikely]]
+            replay();
+    }
+
+    inline void save(size_t slot)
+    {
+        if (m_pending) [[unlikely]]
+        {
+            replay();
+            if (slot >= m_watermark)
+            {
+                if (slot >= m_floor && slot == height)
+                    evict();
+                return;
+            }
+        }
+        if (slot < tagged_slots)
+        {
+            if (m_tags[slot] == m_epoch)
+                return;
+            m_tags[slot] = m_epoch;
+        }
+        if (m_used == UndoBlock::size) [[unlikely]]
+            grow();
+        m_block->value[m_used] = m_base[slot];
+        m_block->slot[m_used] = static_cast<uint16_t>(slot);
+        ++m_used;
+    }
+
+    inline void next_epoch() noexcept
+    {
+        m_epoch = static_cast<Epoch>(static_cast<uint8_t>(m_epoch) + 1);
+        if (m_epoch == Epoch{}) [[unlikely]]
+        {
+            std::fill(m_tags, m_tags + tagged_slots, Epoch{});
+            m_epoch = Epoch{1};
+        }
+    }
+
+    [[nodiscard]] bool in_space(const UndoBlock* block) const noexcept
+    {
+        const auto address = reinterpret_cast<uintptr_t>(block);
+        const auto begin = reinterpret_cast<uintptr_t>(m_base);
+        return address >= begin && address < begin + size_t{m_end} * sizeof(uint256);
+    }
+
+    /// Returns an unused heap block.
+    UndoBlock* heap_block()
+    {
+        UndoBlock* block = m_spare;
+        if (block == nullptr)
+            return new UndoBlock;
+        m_spare = block->prev;
+        return block;
+    }
+
+    /// Continues the log in a new block, in the stack space if it fits above the watermark
+    /// and above the items with a margin: an instruction may still use items it has popped,
+    /// and may push one.
+    [[gnu::noinline]] void grow()
+    {
+        const size_t in_use = std::max<size_t>(height + popped_margin, m_watermark);
+        UndoBlock* block;
+        if (m_floor >= in_use + block_slots)
+        {
+            m_floor -= block_slots;
+            block = ::new (static_cast<void*>(m_base + m_floor)) UndoBlock;
+        }
+        else
+            block = heap_block();
+        block->prev = m_block;
+        m_block = block;
+        m_used = 0;
+        ++m_blocks;
+    }
+
+    /// Moves the undo blocks out of the stack space before the stack grows into them.
+    [[gnu::noinline]] void evict()
+    {
+        for (UndoBlock** link = &m_block; *link != nullptr; link = &(*link)->prev)
+        {
+            if (in_space(*link))
+            {
+                UndoBlock* const copy = heap_block();
+                std::copy((*link)->value, (*link)->value + UndoBlock::size, copy->value);
+                std::copy((*link)->slot, (*link)->slot + UndoBlock::size, copy->slot);
+                copy->prev = (*link)->prev;
+                *link = copy;
+            }
+        }
+        m_floor = m_end;
+    }
+
+    /// Replays the undo log backwards down to m_target entries.
+    [[gnu::noinline]] void replay() const noexcept
+    {
+        m_pending = false;
+        m_watermark = m_restored_watermark;
+        uint256* const base = m_base;
+        const uint32_t target_block = m_target / UndoBlock::size;
+        const uint32_t target_used = m_target % UndoBlock::size;
+        UndoBlock* block = m_block;
+        uint32_t used = m_used;
+        uint32_t blocks = m_blocks;
+        while (blocks - 1 > target_block)
+        {
+            for (uint32_t i = used; i-- != 0;)
+                base[block->slot[i]] = block->value[i];
+            UndoBlock* const prev = block->prev;
+            if (in_space(block))
+                m_floor += block_slots;
+            else
+            {
+                block->prev = m_spare;
+                m_spare = block;
+            }
+            block = prev;
+            --blocks;
+            used = UndoBlock::size;
+        }
+        for (uint32_t i = used; i-- != target_used;)
+            base[block->slot[i]] = block->value[i];
+        m_block = block;
+        m_used = target_used;
+        m_blocks = blocks;
+    }
+
+    /// Copies the state of `other` with the whole undo log in new heap blocks.
+    void copy_from(const StackTop& other)
+    {
+        other.settle();
+        height = other.height;
+        m_watermark = other.m_watermark;
+        m_pending = false;
+        m_epoch = other.m_epoch;
+        m_used = other.m_used;
+        m_blocks = other.m_blocks;
+        m_target = 0;
+        m_end = other.m_end;
+        m_floor = other.m_end;
+        m_spare = nullptr;
+        std::copy(other.m_tags, other.m_tags + tagged_slots, m_tags);
+        m_owned = other.m_owned;
+        if (m_owned)
+        {
+            m_base = new uint256[m_end];
+            std::copy(other.m_base, other.m_base + m_end, m_base);
+        }
+        else
+            m_base = other.m_base;
+        UndoBlock** link = &m_block;
+        for (const UndoBlock* block = other.m_block; block != nullptr; block = block->prev)
+        {
+            UndoBlock* const copy = new UndoBlock;
+            std::copy(block->value, block->value + UndoBlock::size, copy->value);
+            std::copy(block->slot, block->slot + UndoBlock::size, copy->slot);
+            *link = copy;
+            link = &copy->prev;
+        }
+        *link = nullptr;
+    }
+
+    /// Moves the state of `other` here and leaves `other` empty.
+    void take(StackTop& other) noexcept
+    {
+        other.settle();
+        height = other.height;
+        m_base = other.m_base;
+        m_watermark = other.m_watermark;
+        m_pending = false;
+        m_epoch = other.m_epoch;
+        m_owned = other.m_owned;
+        m_floor = other.m_floor;
+        m_used = other.m_used;
+        m_blocks = other.m_blocks;
+        m_target = 0;
+        m_end = other.m_end;
+        m_block = other.m_block;
+        m_spare = other.m_spare;
+        std::copy(other.m_tags, other.m_tags + tagged_slots, m_tags);
+        other.height = 0;
+        other.m_watermark = 0;
+        other.m_used = UndoBlock::size;
+        other.m_blocks = 0;
+        other.m_block = nullptr;
+        other.m_spare = nullptr;
+        if (other.m_owned)
+        {
+            other.m_owned = false;
+            other.m_base = nullptr;
+            other.m_end = 0;
+        }
+        other.m_floor = other.m_end;
+    }
+
+    void release() noexcept
+    {
+        for (UndoBlock* list : {m_block, m_spare})
+        {
+            while (list != nullptr)
+            {
+                UndoBlock* const prev = list->prev;
+                if (!in_space(list))
+                    delete list;
+                list = prev;
+            }
+        }
+        m_block = nullptr;
+        m_spare = nullptr;
+        if (m_owned)
+            delete[] m_base;
+        m_owned = false;
     }
 };

